class Solution {
 int mask(const string&s){int x=0;for(char c:s)x|=1<<(c-'a');return x;}
public:
 int wordCount(vector<string>& startWords,vector<string>& targetWords){
  unordered_set<int> starts;for(auto&s:startWords)starts.insert(mask(s));int ans=0;
  for(auto&s:targetWords){int x=mask(s);for(char c:s){if(starts.count(x^(1<<(c-'a')))){++ans;break;}}}
  return ans;
 }
};
